const dados = $('02_normalizacao_lead').item.json;
const mensalidadeTef = $('08_calculo_tef').item.json.mensalidade_tef;

let franquiaGateway = 0;
let tipoGateway = '';
try {
  if (dados.tem_gateway) {
    const todasLinhas = $('09a_gateway_franquia').all().map(item => item.json);
const linha = todasLinhas.find(l => Number(l.faixa_min) === Number(dados.gateway_faixa_min));
    franquiaGateway = linha ? linha.franquia_mensal : 'negociar';
    tipoGateway = (dados.recorrente_ou_avulsa || '').toLowerCase().includes('recorrente')
      ? 'Gateway Recorrência'
      : 'Gateway Padrão';
  }
} catch (e) {
  franquiaGateway = 0;
}

let taxasC6Pay = [];
try {
  if (dados.tem_c6pay) {
    taxasC6Pay = $('10a2_agrupa_c6pay').item.json.taxas_c6pay;
  }
} catch (e) {
  taxasC6Pay = [];
}

const precisaEscalonamentoGateway = franquiaGateway === 'negociar';

return {
  json: {
    ...dados,
    mensalidade_tef: mensalidadeTef,
    franquia_gateway: franquiaGateway,
    tipo_gateway: tipoGateway,
    taxas_c6pay: taxasC6Pay,
    precisa_escalonamento_gateway: precisaEscalonamentoGateway,
  }
};

// Filtra as 5 linhas certas (uma por modalidade) para a faixa/recebimento do lead
const dados = $('02_normalizacao_lead').item.json;

let linhas = [];
if (dados.tem_c6pay) {
  linhas = $input.all()
    .map(item => item.json)
    .filter(l => l.faixa_tpv === dados.tpv_codigo && l.recebimento === dados.modelo_recebimento_codigo);
}

return { json: { taxas_c6pay: linhas } };

const p = $('11_consolidacao_final').item.json;

// --- Contato completo ---
const contato = `${p.nome_contato || ''} ${p.sobrenome_contato || ''}`.trim();

// --- Identificação / controle ---
const numero_proposta = p.lead_id || String($now.toMillis());
const data_proposta = $now.toFormat('dd/MM/yyyy');
const validade_dias = '30';

// --- Adesão ---
const adesao = p.isencao === 'Sim' ? 'Isenta (conta C6 Bank)' : 'R$ 200,00';

// --- Gateway ---
let gateway_franquia;
if (p.franquia_gateway === 'negociar') {
  gateway_franquia = 'A negociar com nossa equipe comercial';
} else if (typeof p.franquia_gateway === 'number' && p.franquia_gateway > 0) {
  gateway_franquia = `R$ ${p.franquia_gateway.toFixed(2).replace('.', ',')}`;
} else {
  gateway_franquia = '-';
}

// --- C6 Pay ---
function taxaPorModalidade(modalidade) {
  const linha = (p.taxas_c6pay || []).find(r => r.modalidade === modalidade);
  return linha ? linha.taxa.replace('.', ',') : '-';
}
const c6pay_taxa_debito            = taxaPorModalidade('Débito');
const c6pay_taxa_credito_vista     = taxaPorModalidade('Crédito à vista');
const c6pay_taxa_parcelado_2_6     = taxaPorModalidade('Parcelado 2 a 6');
const c6pay_taxa_parcelado_7_12    = taxaPorModalidade('Parcelado 7 a 12');
const c6pay_taxa_adicional_parcela = taxaPorModalidade('Adicional por parcela');

// --- Mensalidade total e produtos contratados ---
const valorGatewayNum = (typeof p.franquia_gateway === 'number') ? p.franquia_gateway : 0;
const mensalidade_total = `R$ ${((p.mensalidade_tef || 0) + valorGatewayNum).toFixed(2).replace('.', ',')}`;

const listaProdutos = [];
if (p.tem_tef) listaProdutos.push('TEF (PayGo)');
if (p.tem_gateway) listaProdutos.push(p.tipo_gateway || 'Gateway');
if (p.tem_c6pay) listaProdutos.push('C6 Pay');
if (p.conta_digital === 'Sim') listaProdutos.push('Conta Digital C6 Bank');
const produtos_contratados = listaProdutos.join(', ') || '-';

// --- Objeto final de valores ---
const valores = {
  numero_proposta,
  data_proposta,
  validade_dias,
  razao_social: p.razao_social || '-',
  cnpj: p.cnpj || '-',
  contato: contato || '-',
  email: p.email || '-',
  telefone: p.telefone || '-',
  qtd_caixas: p.tem_tef ? String(p.qtd_caixas) : 'Não contratado',
  sistema_pdv: p.tem_tef ? (p.sistema_pdv || 'A confirmar') : '-',
  mensalidade_tef: p.tem_tef ? `R$ ${(p.mensalidade_tef || 0).toFixed(2).replace('.', ',')}` : 'R$ 0,00',
  gateway_tipo: p.tem_gateway ? (p.tipo_gateway || '-') : '-',
  gateway_franquia: p.tem_gateway ? gateway_franquia : '-',
  gateway_volume_transacoes: p.tem_gateway ? (p.volume_transacoes_gateway || '-') : '-',
  c6pay_faixa_tpv: p.tem_c6pay ? (p.tpv || '-') : '-',
  c6pay_recebimento: p.tem_c6pay ? (p.modelo_recebimento || '-') : '-',
  c6pay_taxa_debito: p.tem_c6pay ? c6pay_taxa_debito : '-',
  c6pay_taxa_credito_vista: p.tem_c6pay ? c6pay_taxa_credito_vista : '-',
  c6pay_taxa_parcelado_2_6: p.tem_c6pay ? c6pay_taxa_parcelado_2_6 : '-',
  c6pay_taxa_parcelado_7_12: p.tem_c6pay ? c6pay_taxa_parcelado_7_12 : '-',
  c6pay_taxa_adicional_parcela: p.tem_c6pay ? c6pay_taxa_adicional_parcela : '-',
  adesao,
  mensalidade_total,
  produtos_contratados,
};

// --- Monta os requests do batchUpdate ---
const requests = Object.entries(valores).map(([campo, valor]) => ({
  replaceAllText: {
    containsText: { text: `{{${campo}}}`, matchCase: true },
    replaceText: String(valor),
  }
}));

// Preserva o id do documento (vindo do 14_duplicar_template) e adiciona os requests
return {
  json: {
    ...$json,   // id, name, kind, mimeType do Google Drive
    requests,
  }
};
